"""Locally authored machine-learning flashcards with editable reference rubrics."""
SOURCE='https://scikit-learn.org/stable/user_guide.html'
# topic, question, reference answer, groups of acceptable key terms
ML=[
('线性回归','线性回归的最小二乘目标是什么？','最小化预测值与真实值之间的残差平方和。模型对参数是线性的；特征可以经过非线性变换。',[['残差','误差'],['平方']]),
('逻辑回归','逻辑回归为什么能做二分类？','将线性得分通过 sigmoid 映射成二分类概率，常用对数损失训练，再按阈值决定类别。',[['sigmoid','逻辑函数'],['概率'],['阈值']]),
('L1 / L2','L1 与 L2 正则化有什么区别？','L1 惩罚系数绝对值之和，常产生稀疏系数；L2 惩罚系数平方和，通常使系数平滑缩小，但一般不会精确变为零。',[['L1'],['稀疏','零'],['L2'],['缩小','收缩']]),
('偏差与方差','什么是偏差和方差？','偏差描述模型平均预测与真实规律之间的系统性差异；方差描述模型对训练样本变化的敏感性。模型复杂度会影响两者。',[['系统','平均预测'],['训练样本','数据变化'],['敏感','波动']]),
('过拟合','训练效果好但验证效果差，应如何排查？','先检查划分、泄漏与分布差异，再考虑过拟合；可用正则化、简化模型、增加有效数据和早停，并根据验证结果选择方案。',[['划分','泄漏','分布'],['正则','简化','早停']]),
('交叉验证','K 折交叉验证如何工作？','把数据分成 K 份，每轮以一份验证、其余训练，得到 K 次评估后汇总。时间序列或同一主体的重复样本要采用适合的划分，避免泄漏。',[['K','k'],['验证'],['训练'],['汇总','平均']]),
('数据泄漏','为什么标准化不能先对全量数据 fit？','全量 fit 会利用验证或测试数据的统计信息，导致泄漏。应仅在训练部分拟合变换，再将同一变换用于验证和测试；交叉验证中每折分别拟合。',[['训练'],['泄漏'],['验证','测试']]),
('标准化','标准化与归一化有什么区别？','标准化常指减均值除标准差；归一化可能指缩放至固定范围，也可能指将单个样本变成单位范数，需明确具体定义。所有拟合统计量仅来自训练数据。',[['均值'],['标准差'],['范围','范数']]),
('SVM','支持向量机中的间隔是什么意思？','间隔衡量分隔超平面与边界附近样本的距离。线性 SVM 在约束或软间隔惩罚下寻找较大间隔；支持向量决定最终边界。',[['超平面','边界'],['距离'],['支持向量']]),
('核方法','核技巧解决了什么问题？','用核函数直接计算某个特征空间中的内积，而不显式构造该空间的特征，从而可在原空间学习非线性边界。有效核需满足相应条件。',[['内积'],['不显式','无需显式'],['非线性']]),
('决策树','决策树如何选择分类分裂？','评估候选分裂后的子节点纯度或不纯度下降，常用 Gini 或熵。贪心选择当前分裂，并用深度、样本数或剪枝限制复杂度。',[['Gini','熵','不纯度'],['分裂'],['贪心']]),
('随机森林','随机森林为什么能降低方差？','对自助采样得到的数据训练多棵树，并在分裂时随机选择候选特征，使树之间减少相关性；通过平均或投票降低总体方差。',[['采样'],['特征'],['相关'],['平均','投票']]),
('Bagging / Boosting','Bagging 与 Boosting 的核心区别是什么？','Bagging 通常并行训练多个基学习器并聚合，主要降低方差；Boosting 顺序加入学习器，针对当前集成的不足优化损失。实际效果受基学习器和配置影响。',[['并行'],['顺序','串行'],['聚合','集成']]),
('梯度提升','梯度提升树下一棵树学习什么？','学习当前损失关于模型预测的负梯度方向，用新树近似该方向，再以学习率缩小更新；平方误差下负梯度与残差成比例。',[['负梯度'],['损失'],['学习率']]),
('KNN','KNN 的 k 太小和太大分别可能怎样？','k 太小容易受噪声影响，方差较大；k 太大可能过度平滑、偏差较大。距离度量和特征尺度同样重要，应通过验证选择。',[['噪声','方差'],['平滑','偏差'],['距离','尺度']]),
('朴素贝叶斯','朴素贝叶斯的“朴素”假设是什么？','给定类别时各特征条件独立。利用贝叶斯公式将类别先验与特征条件似然组合；条件独立是建模假设，实际数据未必严格满足。',[['给定类别','给定分类'],['条件独立'],['先验','似然']]),
('PCA','PCA 寻找的方向是什么？','在中心化数据上寻找使投影方差最大的正交方向，常通过协方差矩阵特征分解或 SVD 得到。它不使用类别标签，最大方差不等于最强分类能力。',[['方差最大','最大方差'],['正交'],['标签','无监督']]),
('K-Means','K-Means 优化什么目标？','最小化样本到所属簇中心的平方距离之和，交替执行最近中心分配与均值更新。结果受初始化、尺度和簇形状影响，可能落入局部最优。',[['平方距离','距离平方'],['中心'],['均值']]),
('DBSCAN','DBSCAN 与 K-Means 有何不同？','DBSCAN 按密度连接样本，使用邻域半径和最小样本数，可标记噪声且不需预先给簇数；K-Means 需要指定簇数，倾向于适配紧凑簇。',[['密度'],['噪声'],['簇数']]),
('Precision / Recall','Precision 与 Recall 各自的分母是什么？','Precision=TP/(TP+FP)，分母是预测为正的数量；Recall=TP/(TP+FN)，分母是实际为正的数量。分母为零时需约定处理方式。',[['TP+FP'],['TP+FN']]),
('F1','F1 为什么不是 Precision 与 Recall 的算术平均？','F1 是二者的调和平均：2PR/(P+R)，会对其中较低的一项更敏感，适合同时关注两者的情形；仍要结合业务成本与类别分布。',[['调和'],['2PR/(P+R)','2*P*R/(P+R)']]),
('类别不均衡','类别极不均衡时为什么不能只看准确率？','模型总预测多数类也可能得到很高准确率，却漏掉少数类。应查看混淆矩阵、少数类召回、Precision、PR 曲线及业务代价。',[['多数类'],['少数类'],['召回','PR','混淆矩阵']]),
('ROC / PR','ROC 曲线与 PR 曲线分别比较什么？','ROC 比较不同阈值下的 TPR 与 FPR；PR 比较 Precision 与 Recall。严重类别不均衡时 PR 往往更能显示正类预测的实际质量，但仍需结合任务目标。',[['TPR'],['FPR'],['Precision'],['Recall']]),
('概率校准','概率校准与分类准确率是同一件事吗？','不是。校准关注预测概率与经验发生频率是否一致；准确率关注阈值或最大概率决定的类别是否正确。校准好不保证区分能力强，反之亦然。',[['概率'],['频率'],['类别','阈值']]),
('超参数搜索','网格搜索与随机搜索有什么区别？','网格搜索遍历预设参数组合；随机搜索从给定分布或候选范围采样组合。二者都应在验证或交叉验证中选择参数，独立测试集留作最终评估。',[['遍历'],['采样','随机'],['验证']]),
('早停','早停根据训练损失还是验证表现决定？','通常依据验证指标是否持续改善，设定耐心值并保留最佳模型。只看训练损失可能无法及时发现泛化变差；测试集不应用于早停。',[['验证'],['耐心','patience'],['最佳','最好']]),
('特征选择','特征选择与特征提取有什么区别？','特征选择保留原有特征的子集；特征提取将原特征变换成新表示，例如 PCA。选择或提取的拟合步骤都必须放在训练划分内。',[['子集'],['变换','新表示'],['训练']]),
('Pipeline','为什么把预处理和模型放进 Pipeline？','让预处理与模型作为整体拟合、预测和搜索；在交叉验证的每个训练折内拟合预处理，有助于避免数据泄漏并统一推理流程。',[['预处理'],['交叉验证','训练折'],['泄漏']]),
('时间序列划分','时间序列为什么通常不能随机打乱后划分？','随机划分可能让未来信息进入训练，从而高估真实预测表现。应尊重时间顺序，用过去训练、未来验证，必要时设置时间间隔。',[['未来'],['时间顺序','过去'],['泄漏','高估']]),
('模型解释','排列重要性如何衡量特征贡献？','在指定评估数据上打乱一个特征，观察评分下降。下降越大通常表明模型更依赖该特征；相关特征会影响解释，重要性不等于因果作用。',[['打乱','置换'],['评分','性能'],['因果','相关']]),
]
